create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now());
create table if not exists public.organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'viewer',created_at timestamptz not null default now(),unique(organization_id,user_id));
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid references public.branches(id),sku text not null,name text not null,category text,price_usd numeric(18,4) not null default 0,stock numeric(18,4) not null default 0,status text not null default 'Activo',created_at timestamptz not null default now());
create index if not exists products_org_idx on public.products(organization_id);
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,email text,phone text,balance numeric(18,4) not null default 0,status text not null default 'Activo',created_at timestamptz not null default now());
create index if not exists customers_org_idx on public.customers(organization_id);
create table if not exists public.exchange_rates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,base_currency text not null,quote_currency text not null,rate numeric(24,10) not null,source text,observed_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id),action text not null,entity text,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.branches enable row level security; alter table public.products enable row level security; alter table public.customers enable row level security; alter table public.exchange_rates enable row level security; alter table public.audit_logs enable row level security;
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=auth.uid()); $$;
create policy "members can read organizations" on public.organizations for select using (public.is_org_member(id));
create policy "members read memberships" on public.organization_members for select using (user_id=auth.uid() or public.is_org_member(organization_id));
create policy "members read branches" on public.branches for select using (public.is_org_member(organization_id));
create policy "members manage products" on public.products for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "members manage customers" on public.customers for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy "members read rates" on public.exchange_rates for select using (public.is_org_member(organization_id));
create policy "members read audit" on public.audit_logs for select using (public.is_org_member(organization_id));
